/* =========================================================
   SQLite (Expo SDK 54 í˜¸í™˜)
   ========================================================= */
let db = null;
let dbOpenPromise = null;
let dbLastSuccessTime = 0; // ë§ˆì§€ë§‰ ì„±ê³µ ì‹œê°„

// ðŸ”§ v3.4.7: ë°ì´í„°ë² ì´ìŠ¤ ì´ˆê¸°í™” (ê°•í™”ëœ ìž¬ì—°ê²° ë¡œì§)
async function openDb() {
  // ì´ë¯¸ ì—°ê²° ì‹œë„ ì¤‘ì´ë©´ í•´ë‹¹ Promiseë¥¼ ê¸°ë‹¤ë¦¼
  if (dbOpenPromise) {
    try {
      return await dbOpenPromise;
    } catch (e) {
      dbOpenPromise = null;
      db = null;
    }
  }
  
  // ê¸°ì¡´ ì—°ê²°ì´ ìžˆê³ , ìµœê·¼ ì„±ê³µí–ˆìœ¼ë©´ ìž¬ì‚¬ìš©
  if (db && Date.now() - dbLastSuccessTime < 5000) {
    return db;
  }
  
  // ê¸°ì¡´ ì—°ê²°ì´ ìžˆìœ¼ë©´ í…ŒìŠ¤íŠ¸
  if (db) {
    try {
      // ê°„ë‹¨í•œ ì¿¼ë¦¬ë¡œ ì—°ê²° í…ŒìŠ¤íŠ¸
      await db.getAllAsync("SELECT 1;");
      dbLastSuccessTime = Date.now();
      return db;
    } catch (e) {
      // ì—°ê²°ì´ ì£½ì—ˆìœ¼ë©´ ì •ë¦¬
      console.warn("DB ì—°ê²° í…ŒìŠ¤íŠ¸ ì‹¤íŒ¨:", e.message);
      db = null;
    }
  }
  
  // ìƒˆ ì—°ê²° ìƒì„±
  dbOpenPromise = SQLite.openDatabaseAsync("novel_tiers.db");
  
  try {
    db = await dbOpenPromise;
    // 🔧 v3.5.3: WAL 모드 + busy_timeout 설정 (동시 접근 안정성 대폭 향상)
    // WAL: 쓰기 중에도 읽기 가능, busy_timeout: 잠금 시 5초 대기 후 에러
    await db.runAsync("PRAGMA journal_mode=WAL;");
    await db.runAsync("PRAGMA busy_timeout=5000;");
    dbLastSuccessTime = Date.now();
    console.log("DB ì—°ê²° ì„±ê³µ (WAL mode)");
    return db;
  } catch (e) {
    console.error("DB ì—´ê¸° ì‹¤íŒ¨:", e.message);
    db = null;
    throw e;
  } finally {
    dbOpenPromise = null;
  }
}

// DB ì—°ê²° ê°•ì œ ë¦¬ì…‹
function resetDbConnection() {
  console.log("DB ì—°ê²° ë¦¬ì…‹");
  db = null;
  dbOpenPromise = null;
  dbLastSuccessTime = 0;
}

// ðŸ”§ v3.4.7: ì•ˆì „í•œ DB ì‹¤í–‰ ëž˜í¼ (ìžë™ ìž¬ì—°ê²° + ë” ì ê·¹ì ì¸ ìž¬ì‹œë„)
async function safeDbOperation(operation, operationName = "DB") {
  const maxRetries = 5; // 3 â†’ 5ë¡œ ì¦ê°€
  
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      // ë§¤ ì‹œë„ë§ˆë‹¤ ì—°ê²° í™•ì¸
      const database = await openDb();
      if (!database) {
        throw new Error("Database is null after openDb");
      }
      
      const result = await operation(database);
      dbLastSuccessTime = Date.now();
      return result;
    } catch (e) {
      const errorMsg = e.message || "";
      const isConnectionError = 
        errorMsg.includes("NullPointerException") ||
        errorMsg.includes("prepareAsync") ||
        errorMsg.includes("rejected") ||
        errorMsg.includes("database") ||
        errorMsg.includes("null") ||
        errorMsg.includes("closed");
      
      console.warn(`${operationName} ì˜¤ë¥˜ (ì‹œë„ ${attempt + 1}/${maxRetries}):`, errorMsg);
      
      if (isConnectionError || attempt > 0) {
        // ì—°ê²° ì˜¤ë¥˜ê±°ë‚˜ ë‘ ë²ˆì§¸ ì‹œë„ë¶€í„°ëŠ” í•­ìƒ ë¦¬ì…‹
        resetDbConnection();
      }
      
      if (attempt === maxRetries - 1) {
        throw e;
      }
      
      // ì ì§„ì  ëŒ€ê¸° (ë” ê¸¸ê²Œ)
      await new Promise(r => setTimeout(r, 300 * (attempt + 1)));
    }
  }
}

/** ë‹¨ì¼ ì¿¼ë¦¬ ì‹¤í–‰ */
async function exec(sql, params = []) {
  return safeDbOperation(
    (database) => database.runAsync(sql, params),
    "exec"
  );
}

/** SELECT ì „ì²´ */
async function all(sql, params = []) {
  return safeDbOperation(
    (database) => database.getAllAsync(sql, params),
    "all"
  );
}

/** SELECT ì²« ë²ˆì§¸ */
async function first(sql, params = []) {
  return safeDbOperation(
    (database) => database.getFirstAsync(sql, params),
    "first"
  );
}

/** íŠ¸ëžœìž­ì…˜ ì‹¤í–‰ */
async function execBatch(queries) {
  if (!queries || queries.length === 0) return;
  
  return safeDbOperation(
    async (database) => {
      await database.withTransactionAsync(async () => {
        for (const { sql, params } of queries) {
          await database.runAsync(sql, params || []);
        }
      });
    },
    "execBatch"
  );
}

/* =========================================================
   ðŸ”„ ë§¤ì¹­ íìž‰ ì‹œìŠ¤í…œ (v3.4.6)
   - ë¹ ë¥¸ ì—°íƒ€ì—ë„ DB íŠ¸ëžœìž­ì…˜ ì¶©ëŒ ë°©ì§€
   - UIëŠ” ì¦‰ì‹œ ì‘ë‹µ, DBëŠ” ìˆœì°¨ ì²˜ë¦¬
   - pending ë§¤ì¹˜ ì¶”ì ìœ¼ë¡œ ì¤‘ë³µ ë°©ì§€
   ========================================================= */
const matchQueue = [];
let isProcessingMatchQueue = false;
let matchQueueUpdateCallback = null; // ìƒíƒœ ì—…ë°ì´íŠ¸ìš© ì½œë°±
const pendingMatchPairs = new Set(); // íì—ì„œ ì²˜ë¦¬ ëŒ€ê¸° ì¤‘ì¸ pair í‚¤ë“¤

// í ìƒíƒœ ì—…ë°ì´íŠ¸ ì½œë°± ë“±ë¡
function setMatchQueueCallback(callback) {
  matchQueueUpdateCallback = callback;
}

// í ìƒíƒœ ì•Œë¦¼
function notifyQueueStatus() {
  if (matchQueueUpdateCallback) {
    matchQueueUpdateCallback({
      pending: matchQueue.length,
      processing: isProcessingMatchQueue
    });
  }
}

// pair í‚¤ ìƒì„± í—¬í¼ (ì¤‘ë³µ ì²´í¬ìš©)
function matchPairKey(aId, bId) {
  return aId < bId ? `${aId}|${bId}` : `${bId}|${aId}`;
}

// ë§¤ì¹˜ê°€ ì´ë¯¸ íì— ìžˆëŠ”ì§€ í™•ì¸
function isMatchPending(aId, bId) {
  return pendingMatchPairs.has(matchPairKey(aId, bId));
}

// ë§¤ì¹­ ìž‘ì—…ì„ íì— ì¶”ê°€ (pairKeyë„ í•¨ê»˜ ì¶”ì )
function enqueueMatchTask(task, pairKey = null) {
  return new Promise((resolve, reject) => {
    // ì¤‘ë³µ ë°©ì§€: ì´ë¯¸ íì— ìžˆìœ¼ë©´ ë¬´ì‹œ
    if (pairKey && pendingMatchPairs.has(pairKey)) {
      console.log("ë§¤ì¹˜ í: ì´ë¯¸ ëŒ€ê¸° ì¤‘ì¸ ì¡°í•©, ë¬´ì‹œ:", pairKey);
      resolve(null);
      return;
    }
    
    if (pairKey) {
      pendingMatchPairs.add(pairKey);
    }
    
    matchQueue.push({ task, resolve, reject, pairKey });
    notifyQueueStatus();
    processMatchQueue();
  });
}

// í ìˆœì°¨ ì²˜ë¦¬
async function processMatchQueue() {
  if (isProcessingMatchQueue) return;
  isProcessingMatchQueue = true;
  notifyQueueStatus();
  
  while (matchQueue.length > 0) {
    const { task, resolve, reject, pairKey } = matchQueue.shift();
    notifyQueueStatus();
    
    try {
      const result = await task();
      resolve(result);
    } catch (e) {
      console.warn("ë§¤ì¹­ í ì²˜ë¦¬ ì˜¤ë¥˜:", e.message);
      reject(e);
    } finally {
      // ì²˜ë¦¬ ì™„ë£Œ í›„ pendingì—ì„œ ì œê±°
      if (pairKey) {
        pendingMatchPairs.delete(pairKey);
      }
    }
    
    // ê° ìž‘ì—… ì‚¬ì´ì— ì•½ê°„ì˜ ë”œë ˆì´ (DB ì•ˆì •ì„±)
    await new Promise(r => setTimeout(r, 50));
  }
  
  isProcessingMatchQueue = false;
  notifyQueueStatus();
}

/* -------------------- Migration -------------------- */
async function columnExists(table, name) {
  const rows = await all(`PRAGMA table_info(${table});`);
  return rows.some((r) => r.name === name);
}

async function ensureColumn(table, name, type, defaultExpr) {
  const exists = await columnExists(table, name);
  if (!exists) {
    await exec(
      `ALTER TABLE ${table} ADD COLUMN ${name} ${type}${
        defaultExpr ? " DEFAULT " + defaultExpr : ""
      };`
    );
  }
}

// ðŸ”§ v3.4.6: íƒ€ìž„ìŠ¤íƒ¬í”„ + ì¹´ìš´í„°ë¡œ ì¤‘ë³µ ë°©ì§€ ê°•í™”
let uuidCounter = 0;
function uuid() {
  const timestamp = Date.now().toString(36);
  const counter = (uuidCounter++ % 1000).toString(36).padStart(3, '0');
  const random = "xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0,
      v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
  return `${timestamp}${counter}-${random}`;
}

