      const dupPlanned = await first("SELECT id FROM planned_novels WHERE title=?", [t]);
      if (dupMain || dupPlanned) {
        setIsLoading(false);
        Alert.alert("ì•Œë¦¼", "ê°™ì€ ì œëª©ì´ ì´ë¯¸ ìžˆìŠµë‹ˆë‹¤.");
        return;
      }
      
      const id = uuid();
